create table supplier (id bigint generated by default as identity primary key, name varchar(160) not null, external_code varchar(64) not null unique);
create table customer (id bigint generated by default as identity primary key, name varchar(160) not null, external_code varchar(64) not null unique);
create table product (id bigint generated by default as identity primary key, sku varchar(64) not null unique, name varchar(160) not null);
create table inventory_balance (product_id bigint primary key references product(id), physical bigint not null default 0 check (physical >= 0), reserved bigint not null default 0 check (reserved >= 0 and reserved <= physical), average_cost numeric(19,4) not null default 0 check (average_cost >= 0));
create table purchase_order (id bigint generated by default as identity primary key, supplier_id bigint not null references supplier(id), created_by varchar(100) not null, created_at timestamptz not null default now(), received_at timestamptz);
create table purchase_line (id bigint generated by default as identity primary key, purchase_id bigint not null references purchase_order(id), product_id bigint not null references product(id), quantity bigint not null check (quantity > 0), unit_cost numeric(19,4) not null check (unit_cost >= 0), unique(purchase_id, product_id));
create table sales_order (id bigint generated by default as identity primary key, customer_id bigint not null references customer(id), created_by varchar(100) not null, created_at timestamptz not null default now(), status varchar(20) not null check (status in ('CRIADO','RESERVADO')), idempotency_key varchar(120) not null unique, request_hash varchar(64) not null);
create table sales_line (id bigint generated by default as identity primary key, sales_order_id bigint not null references sales_order(id), product_id bigint not null references product(id), quantity bigint not null check (quantity > 0), unique(sales_order_id, product_id));
create table inventory_ledger (id bigint generated by default as identity primary key, product_id bigint not null references product(id), kind varchar(20) not null check (kind in ('RECEIPT','RESERVATION')), physical_delta bigint not null, reserved_delta bigint not null, source_type varchar(30) not null, source_id bigint not null, actor varchar(100) not null, occurred_at timestamptz not null default now(), check ((kind = 'RECEIPT' and physical_delta > 0 and reserved_delta = 0) or (kind = 'RESERVATION' and physical_delta = 0 and reserved_delta > 0)), unique(product_id, kind, source_type, source_id));
create index idx_inventory_ledger_product on inventory_ledger(product_id, id);
create function forbid_ledger_mutation() returns trigger language plpgsql as $$ begin raise exception 'inventory_ledger is append-only'; end; $$;
create trigger inventory_ledger_append_only before update or delete on inventory_ledger for each row execute function forbid_ledger_mutation();
